if __name__ == "__main__":
    path = os.path.join(HERE, "india_testset.csv")
    with open(path, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(["text", "label", "kind"])
        for k, t in SCAM:
            w.writerow([t, 1, k])
        for k, t in LEGIT:
            w.writerow([t, 0, k])
    print("devset: %d scam, %d legit -> %s" % (len(SCAM), len(LEGIT), path))
